    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xE64A2150F70885F7ULL + 0xD252E8632189FD52ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0xF587F1DBBA680A7DULL + 0xBC511623A8966BABULL);
