            aOrbiterI = ((aWandererI + RotL64(aPrevious, 29U)) + 0x949BE517AF85259DULL) + aOrbiterAssignSaltE[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterD = ((aWandererJ + RotL64(aIngress, 57U)) + 0x43969CC46C1AC495ULL) + aOrbiterAssignSaltF[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterB = (aWandererG + RotL64(aCross, 41U)) + 0x1D139EC795CAFE1FULL;
