            aOrbiterD = RotL64((aOrbiterD * 0x7F65ACB0A065653FULL), 29U);
            //
            aOrbiterI = (((aOrbiterI + aOrbiterG) + 0xE8CCE70FA1435E67ULL) + aOrbiterUpdateSaltD[(((31U - aIndex) + 5U)) & S_SALT1]) + aNonceWordO;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0xFB221D55621F3F8AULL;
            aOrbiterB = RotL64((aOrbiterB * 0x2A9B44B3BA04F5E5ULL), 41U);
            //
