            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x38BF3808F218161FULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0x2087E1B26D216C27ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xADB9126EF16FCF69ULL), 3U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x33E1E6C5BA861796ULL;
