            aOrbiterA = RotL64((aOrbiterA * 0xB7E17DD0C62648ABULL), 39U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterE) + 0xDDF654397C7BD434ULL) + aNonceWordA;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x419E32CFE070B69AULL;
            aOrbiterK = RotL64((aOrbiterK * 0x383C8A7E5F64E2C3ULL), 21U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterK) + 0x25502C9E2040D538ULL) + aOrbiterUpdateSaltF[((aIndex + 13U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x01C3E07EEC5D30C7ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x1F5C783796121747ULL), 37U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterD, 41U);
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterB, 30U));
