            aWandererG = aWandererG + ((RotL64(aScatter, 21U) + RotL64(aOrbiterI, 13U)) + aOrbiterE);
            aWandererB = aWandererB ^ ((((RotL64(aIngress, 13U) + RotL64(aOrbiterG, 57U)) + aOrbiterA) + aNonceWordD) + aWandererUpdateSaltF[((aIndex + 23U)) & S_SALT1]);
            aWandererI = aWandererI + ((RotL64(aPrevious, 5U) + RotL64(aOrbiterE, 27U)) + aOrbiterB);
            aWandererC = aWandererC ^ ((RotL64(aCross, 19U) + aOrbiterK) + RotL64(aOrbiterC, 60U));
