    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSource;
    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xD58E007ACB52FA0FULL + 0xE273291C4462E0DEULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0xFC5F7ABDC9AD696DULL + 0x8EF1AE8E71A0A3CBULL);
