            aOrbiterI = ((aWandererA + RotL64(aIngress, 19U)) + RotL64(aCarry, 39U)) + 0xE53A3596678F9A25ULL;
            aOrbiterC = ((aWandererF + RotL64(aCross, 47U)) + RotL64(aCarry, 47U)) + 0x9240F4454858BB28ULL;
            aOrbiterK = (aWandererD + RotL64(aPrevious, 35U)) + 0x28F74BE1C5B0FA2EULL;
            aOrbiterJ = (aWandererB + RotL64(aIngress, 23U)) + 0x92F099CF4D8AC1CFULL;
            aOrbiterD = (aWandererJ + RotL64(aScatter, 5U)) + 0x2369B083B340925EULL;
            aOrbiterH = (((aWandererE + RotL64(aPrevious, 56U)) + RotL64(aCarry, 19U)) + 0x84E60E15A240D687ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 4U)) & S_SALT1];
