            aOrbiterK = (aWandererD + RotL64(aPrevious, 35U)) + 0xAC4575BC59D0D8C1ULL;
            aOrbiterI = (aWandererJ + RotL64(aCross, 3U)) + 0x2F2D63F29F1DC8B6ULL;
            aOrbiterC = (((aWandererB + RotL64(aIngress, 27U)) + RotL64(aCarry, 19U)) + 0x582A6109B6BE67F2ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 16U)) & S_SALT1];
