            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0x4F2A0480A6FA18DEULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0x7544D116B6582FB7ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 9U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xD924903CC1786317ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xE37540BDF66E0CE2ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x9F4EC353108FC6D8ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xD9A217EE0D7A2CADULL), 51U);
            //
            aIngress = aOrbiterD ^ RotL64(aOrbiterH, 27U);
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterC, 46U));
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterK, 21U));
