            //
            aScatter = (RotL64(aCross, 43U) ^ RotL64(aIngress, 60U)) ^ (RotL64(aPrevious, 11U) + RotL64(aCarry, 23U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterB = ((aWandererI + RotL64(aIngress, 13U)) + 0xC86FC8A4F3EB92B3ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterK = (aWandererG + RotL64(aPrevious, 3U)) + 0x032B889F9F0BE616ULL;
            aOrbiterH = (aWandererB + RotL64(aScatter, 21U)) + 0xCB0998CF74C2F47DULL;
