            aOrbiterG = ((aWandererF + RotL64(aScatter, 43U)) + 0xAD074DFB514A8CA0ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterA = ((aWandererH + RotL64(aPrevious, 28U)) + RotL64(aCarry, 57U)) + 0x2E9A833840FD6524ULL;
