            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0x1D3C996C7DFAD0C8ULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0xB591C15795073E2AULL;
            aOrbiterI = RotL64((aOrbiterI * 0xBB741414778EA143ULL), 3U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterF) + 0x22EB3FB32AB911E6ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0xB05099E7CFB5B79CULL;
            aOrbiterB = RotL64((aOrbiterB * 0xA13446D6E4C06591ULL), 41U);
