            aOrbiterI = (aOrbiterI + aOrbiterH) + 0xDC982E9DD90576F7ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0x1E9776490948E1C9ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x656D68C7DBE138BDULL), 11U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterG) + 0xDD0195D45E7CF190ULL) + aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterH) ^ 0x18C70CD7E540D169ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 25U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x15F5260E4C2C1A13ULL), 21U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x5C0824C8E6AC096CULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0xC1BEF95C3C75B5F8ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x8792DD0F64EB789BULL), 57U);
