            aWandererH = aWandererH + (((RotL64(aIngress, 13U) + aOrbiterA) + RotL64(aOrbiterF, 35U)) + RotL64(aCarry, 13U));
            aWandererK = aWandererK ^ ((RotL64(aCross, 5U) + RotL64(aOrbiterA, 29U)) + aOrbiterB);
