            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0xA73E1308C7906E66ULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 17U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x90B7A2ACE8D1047BULL;
            aOrbiterH = RotL64((aOrbiterH * 0x7397720AFA8E9BA5ULL), 3U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0x88A8CAE3E349A254ULL) + aKeyRotateAOrbiterUpdateSaltB[((aIndex + 28U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0xC2E846B3B6B5CB7DULL;
            aOrbiterF = RotL64((aOrbiterF * 0xAAF8D31E7F753A47ULL), 29U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0xA745659BA6A4BAC8ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x4478BD37172BEEF7ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x128955DFCA4B4F89ULL), 27U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0xBD0AD431AD9D3CF9ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x40E5BF9D462EBF27ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xDFA7C3BCD4F748F9ULL), 53U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0x3BBF8A18AFB851CDULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x03A1D4BEE30BB1BBULL;
            aOrbiterB = RotL64((aOrbiterB * 0xACA1BE9C1972B8D5ULL), 39U);
