            aOrbiterA = (aOrbiterA + aOrbiterF) + 0xB5D59CD2E613CBECULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0xECF1AEB9498D23D9ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xE36364FED6F0B70FULL), 37U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterJ) + 0x3D5E8CD337F6123CULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 29U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0x268CF4085C306871ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x71AE17EE7E4E4553ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0xED0E5565574C9A8DULL;
