            aIngress = aOrbiterC ^ RotL64(aOrbiterG, 52U);
            aIngress = aIngress + (RotL64(aOrbiterH, 27U) ^ aOrbiterK);
            aIngress = aIngress + (RotL64(aOrbiterB, 41U) ^ aOrbiterD);
            aIngress = aIngress + (RotL64(aOrbiterJ, 43U) ^ aOrbiterE);
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterA, 23U));
            aIngress = aIngress + RotL64(aOrbiterF, 29U);
