            //
            aWandererI = aWandererI ^ ((RotL64(aIngress, 50U) + RotL64(aOrbiterE, 19U)) + aOrbiterB);
            aWandererE = aWandererE + (((RotL64(aPrevious, 37U) + RotL64(aOrbiterF, 39U)) + aOrbiterG) + aKeyRotateAWandererUpdateSaltC[(((31U - aIndex) + 8U)) & S_SALT1]);
            aWandererB = aWandererB ^ ((RotL64(aScatter, 39U) + aOrbiterD) + RotL64(aOrbiterC, 34U));
            aWandererJ = aWandererJ + (((RotL64(aCross, 3U) + RotL64(aOrbiterA, 11U)) + aOrbiterB) + RotL64(aCarry, 47U));
            aWandererA = aWandererA ^ ((RotL64(aIngress, 5U) + RotL64(aOrbiterC, 13U)) + aOrbiterG);
            aWandererC = aWandererC + ((RotL64(aCross, 35U) + aOrbiterD) + RotL64(aOrbiterJ, 43U));
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 46U) + RotL64(aOrbiterI, 4U)) + aOrbiterG);
            aWandererD = aWandererD + (((RotL64(aScatter, 13U) + aOrbiterF) + RotL64(aOrbiterH, 37U)) + RotL64(aCarry, 37U));
            aWandererK = aWandererK ^ ((RotL64(aIngress, 19U) + RotL64(aOrbiterK, 57U)) + aOrbiterB);
            aWandererF = aWandererF + (((RotL64(aScatter, 57U) + aOrbiterB) + RotL64(aOrbiterI, 23U)) + aKeyRotateAWandererUpdateSaltA[(((31U - aIndex) + 10U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aPrevious, 11U) + aOrbiterE) + RotL64(aOrbiterA, 27U));
