    std::uint64_t *aKeyRotateAOrbiterUpdateSaltC = pWorkSpace->mDomainBundle.mKeyRotateASalts.mOrbiterUpdate.mSaltC;
    std::uint64_t *aKeyRotateAOrbiterUpdateSaltD = pWorkSpace->mDomainBundle.mKeyRotateASalts.mOrbiterUpdate.mSaltD;
    std::uint64_t *aKeyRotateAOrbiterUpdateSaltE = pWorkSpace->mDomainBundle.mKeyRotateASalts.mOrbiterUpdate.mSaltE;
