            //
            aScatter = (RotL64(aPrevious, 54U) ^ RotL64(aCross, 39U)) + (RotL64(aCarry, 11U) + RotL64(aIngress, 23U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterG = ((aWandererA + RotL64(aIngress, 53U)) + RotL64(aCarry, 53U)) + 0xE4AC909F65BE3F3CULL;
            aOrbiterB = ((aWandererD + RotL64(aScatter, 13U)) + RotL64(aCarry, 23U)) + 0xEBDC9D62686C0EE6ULL;
            aOrbiterH = (aWandererK + RotL64(aCross, 21U)) + 0xD795F96B56D3D917ULL;
            aOrbiterI = ((aWandererH + RotL64(aPrevious, 35U)) + 0x4DE4FC78D789CBEDULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterE = (aWandererG + RotL64(aIngress, 60U)) + 0xF570A8DF4C6AACFDULL;
            aOrbiterA = ((aWandererC + RotL64(aCross, 29U)) + RotL64(aCarry, 5U)) + 0x606858BDFAB4A9B2ULL;
            aOrbiterJ = ((aWandererJ + RotL64(aScatter, 47U)) + 0x79A7769DD6B5C042ULL) + aKeyRotateAOrbiterAssignSaltF[((aIndex + 17U)) & S_SALT1];
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0x19584E102EB4983DULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 26U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0x9C3E44A1ED21CB58ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xAEAA8D98949373F7ULL), 41U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0xA8A4CC11231C2E47ULL;
