            aOrbiterA = ((aOrbiterA + aOrbiterJ) + 0xEAC758ACCF2246D0ULL) + aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterA) ^ 0x52FA42F902D82760ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 8U)) & S_SALT1];
