            aOrbiterJ = RotL64((aOrbiterJ * 0x074091AC2E81A8FBULL), 57U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x6F031E6C5B8613DDULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterJ) ^ 0x73B05962671AA3ABULL) ^ aKeyRotateAOrbiterUpdateSaltB[((aIndex + 20U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xD38C91993A1E81A1ULL), 21U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0x874EBBDE8CE79B65ULL;
