            aWandererH = aWandererH ^ (((RotL64(aPrevious, 46U) + RotL64(aOrbiterI, 3U)) + aOrbiterJ) + aKeyRotateAWandererUpdateSaltF[((aIndex + 27U)) & S_SALT1]);
            aWandererA = aWandererA + (((RotL64(aScatter, 27U) + aOrbiterE) + RotL64(aOrbiterJ, 13U)) + RotL64(aCarry, 19U));
