        //
        // Ingress:
        //      aFuseLaneA (-->), aWindLaneC (-->), aHeartLaneD (-->), aPoisonLaneA (<-?->)
        //
        // Cross:
        //      aWindLaneA (<--), aWindLaneD (<--), aKeyRowReadB (<--), aWoodLaneB (<-?->)
        //
        // Destination:
        //      aFuseLaneB
