            //
            aIngress = (RotL64(aFuseLaneA[((aIndex + 9881U)) & S_BLOCK1], 19U) ^ RotL64(aWindLaneC[((aIndex + 10351U)) & S_BLOCK1], 27U));
            aIngress ^= (RotL64(aHeartLaneD[((aIndex + 12184U)) & S_BLOCK1], 54U) ^ RotL64(aPoisonLaneA[((aIndex + 12895U)) & S_BLOCK1], 5U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 10227U)) & S_BLOCK1], 35U) ^ RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 9322U)) & S_BLOCK1], 22U));
            aCross ^= (RotL64(aKeyRowReadB[(((2047U - aIndex) + 15670U)) & W_KEY1], 51U) ^ RotL64(aWoodLaneB[((aIndex + 11804U)) & S_BLOCK1], 3U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 51U) ^ RotL64(aPrevious, 5U)) + (RotL64(aCarry, 19U) + RotL64(aIngress, 38U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterG = (aWandererG + RotL64(aCross, 21U)) + 0x964B2FE4716498E4ULL;
            aOrbiterC = (aWandererI + RotL64(aScatter, 51U)) + 0xB6B780AD57EE72B6ULL;
            aOrbiterK = ((aWandererH + RotL64(aIngress, 29U)) + RotL64(aCarry, 29U)) + 0x74F3076E0ECAC9FDULL;
            aOrbiterA = (aWandererC + RotL64(aPrevious, 37U)) + 0xCA87AB41BFBB5780ULL;
            aOrbiterF = (((aWandererE + RotL64(aCross, 60U)) + RotL64(aCarry, 47U)) + 0x58AEB25A0C06CD20ULL) + aKeyRotateAOrbiterAssignSaltD[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterJ = ((aWandererD + RotL64(aPrevious, 3U)) + RotL64(aCarry, 5U)) + 0x14E6B6FC304EF1B5ULL;
            aOrbiterD = ((aWandererK + RotL64(aScatter, 43U)) + 0xBD02B741A652FC80ULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 27U)) & S_SALT1];
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0xCEC5AACF706C5FC6ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterG) ^ 0xF5FC57339D2CFCC6ULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x2823A5FCFD1B4D75ULL), 21U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterF) + 0x22BA7BC635EFD031ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0xF71A65B08A5BDF89ULL) ^ aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xD4B46E73A828816BULL), 43U);
            //
